export async function autoSeedIfEmpty(): Promise<void> {
  const client = await pool.connect();
  try {
    const result = await client.query('SELECT COUNT(*) FROM admins');
    const count = parseInt(result.rows[0].count, 10);
    if (count > 0) {
      console.log('[seed] Database already seeded, skipping auto-seed');
      return;
    }
    console.log('[seed] Empty database detected — running auto-seed...');
    await client.query('BEGIN');
    for (const stmt of SEED_STATEMENTS) {
      await client.query(stmt);
    }
    await client.query('COMMIT');
    console.log('[seed] Auto-seed complete — ' + SEED_STATEMENTS.length + ' statements executed');
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    console.error('[seed] Auto-seed failed:', err);
  } finally {
    client.release();
  }
}
